def numerical_grad(f, w, h=1e-5):
    grad = []
    for i in range(len(w)):
        up, down = list(w), list(w)
        up[i] += h
        down[i] -= h
        grad.append((f(up) - f(down)) / (2 * h))
    return grad

def rel_error(a, b):
    return max(abs(x - y) / max(1e-12, abs(x) + abs(y)) for x, y in zip(a, b))
